insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 165, 'ആദ്യമായി വസ്ത്രം ധരിപ്പിക്കപ്പെടുന്നവൻ', null, 897 from books where volume_id=1 and book_no=31 on conflict (book_id, chapter_no) do nothing;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ الْحَارِثَ بْنَ هشَام سَأَلَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللهِ، كَيْفَ يَأْتِيكَ الْوَحْيُ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَحْيَانًا يَأْتِيني مثل صَلْصَلَةِ الْجَرَسِ، وَهُوَ أَشدُّهُ عَلَيَّ، فَيُفْصَمُ عَنِّي وَقَدْ وَعَيْتُ عَنهُ مَا قَالَ، وَأَحْيَانًا يَتَمَثَّلُ لِيَ الْمَلَكُ رَجُلًا، فَيُكَلِّمُنِي فَأَعِي مَا يَقُولُ". قَالَتْ عَائِشَةُ رَضِيَ اللهُ عَنْهَا: وَلَقَدْ رَأَيْتُهُ يَنْزِلُ عَلَيْهِ الْوَحْيُ في الْيَوْمِ الشَّدِيدِ الْبَرْدِ فَيَفْصِمُ عَنْهُ وَإِنَّ جَبِينَهُ لَيَتَفَصَّدُ عَرَقًا. (ق,ت,ن)', 'ആഇശ(റ): ഹിശാമിന്റെ മകൻ ഹാരിസ് നബി(സ)യോടു ചോദിച്ചു: ദൈവദൂതരേ! അങ്ങേക്ക് ദിവ്യസന്ദേശം എങ്ങനെയാണ് ലഭിക്കുന്നത്? പ്രവാചകൻ(സ) പറഞ്ഞു: "മണിനാദം മുഴങ്ങുന്നതുപോലെ, ചിലപ്പോൾ എനിക്ക് ദിവ്യസന്ദേശം ലഭിക്കും. ഇതാണ് എനിക്ക് ഏറ്റവും പ്രയാസകരമായത്. അനന്തരം അത് നിലയ്ക്കുമ്പോഴേക്കും ആ (സന്ദേശ വാഹകൻ) പറഞ്ഞത് ഞാൻ ശരിക്കും ഹൃദിസ്ഥമാക്കിയിട്ടുണ്ടാകും. ചിലപ്പോൾ മനുഷ്യരൂപത്തിൽ മലക്ക് എന്റെ മുമ്പിൽ പ്രത്യക്ഷപ്പെട്ട് സംസാരിക്കും. അപ്പോൾ മലക്ക് പറഞ്ഞതെല്ലാം ഞാൻ ഹൃദിസ്ഥമാക്കുകയും ചെയ്യും." ആഇശ(റ) പറയുന്നു: അതി ശൈത്യമുള്ള ദിവസം പ്രവാചകർ(സ)ക്ക് ദിവ്യസന്ദേശം ലഭിക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. അതിൽനിന്ന് വിരമിക്കുമ്പോൾ അവിടുത്തെ നെറ്റിത്തടം വിയർത്തൊലിക്കുന്നുണ്ടാവും. (ബു,മു,തു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 71, 71, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ أَوَّلُ مَا بُدِئَ بِهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنَ الْوَحْيِ الرُّؤْيَا الصَّادِقَةَ في النَّوْمِ، فَكَانَ لَا يَرَى رُؤْيَا إِلَّا جَاءَتْ مِثْلَ فَلَقِ الصُّبْحِ، ثُمَّ حُبِّبَ إِلَيْهِ الْخَلَاءُ، فَكَانَ يَخْلُو بِغَارِ حِرَاءٍ يَتَحَنَّثُ فِيهِنَّ وَهُوَ التَّعَبُّدُ اللَّيَالِيَ أُولَاتِ الْعَدَدِ قَبْلَ أَنْ يَرْجِعَ إِلَى أَهْلِهِ، وَيَتَزَوَّدُ لِذَلِكَ، ثُمَّ يَرْجِعُ إِلَى خَدِيجَةَ، فَيَتَزَوَّدُ لِمثْلِهَا حَتَّى فَجِئَهُ الْحَقُّ وَهُوَ في غَارِ حِرَاءٍ، فَجَاءَهُ الْمَلَكُ فَقَالَ: اقْرَأْ، قَالَ: "مَا أَنَا بِقَارِئٍ". قَالَ: "فَأَخَذَنِي فَغَطَّنِي حَتَّى بَلَغَ مِنِّي الْجَهْدَ، ثُمَّ أَرْسَلَنِي فَقَالَ: اقْرَأْ، قَالَ: قُلْتُ: مَا أَنَا بِقَارِئٍ". قَالَ: "فَأَخَذَنِي فَغَطَّنِي الثَّانِيَةَ حَتَّى بَلَغَ مِنِّي الْجَهْدَ، ثُمَّ أَرْسَلَنِي. فَقَالَ: إِقْرَأْ، فَقُلْتُ: مَا أَنَا بِقَارِئٍ، فَأَخَذَنِي فَغَطَّنِي الثَّالِثَةَ حَتَّى بَلَغَ مِنِّي الْجَهْدَ، ثُمَّ أَرْسَلَنِي فَقَالَ:{اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ، خَلَقَ الْإِنْسَانَ مِنْ عَلَقٍ، اقْرَأْ وَرَبُّكَ الْأَكْرَمُ، الَّذِي عَلَّمَ بِالْقَلَمِ، عَلَّمَ الْإِنْسَانَ مَا لَمْ يَعْلَمْ}" [العلق: ١-٥]. فَرَجَعَ بِهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَرْجُفُ بَوَادِرُهُ حَتَّى دَخَلَ عَلَى خَدِيجَةَ فَقَالَ: "زَمِّلُونِي زَمِّلُونِي". فَزَمَّلُوهُ حَتَّى ذَهَبَ عَنْهُ الرَّوْعُ، ثُمَّ قَالَ لِخَدِيجَةَ: "أَيْ خَدِيجَةُ، مَا لِي". وَأَخْبَرَهَا الْخَبَرَ، قَالَ: "لَقَدْ خَشِيتُ عَلَى نَفْسِي". قَالَتْ لَهُ خَدِيجَةُ: كَلَّا أَبْشِرْ، فَوَاللهِ لَا يُخْزِيكَ اللهُ أَبَدًا، وَاللهِ إِنَّكَ لَتَصِلُ الرَّحِمَ، وَتَصْدُقُ الْحَدِيثَ، وَتَحْمِلُ الْكَلَّ، وَتَكْسِبُ الْمَعْدُومَ، وَتَقْرِي الضَّيْفَ، وَتُعِينُ عَلَى نَوَائِبِ الْحَقِّ. فَانْطَلَقَتْ بِهِ خَدِيجَةُ حَتَّى أَتَتْ بِهِ وَرَقَةَ بْنَ نَوْفَلِ بْنِ أَسَدِ بْنِ عَبْدِ الْعُزَّى، وَهُوَ ابْنُ عَمِّ خَدِيجَةَ، أَخِي أَبِيهَا، وَكَانَ امْرَأً تَنَصَّرَ في الْجَاهِلِيَّةِ، وَكَانَ يَكْتُبُ الْكِتَابَ الْعَرَبِيَّ، وَيَكْتُبُ مِنَ الْإِنْجِيلِ بِالْعَرَبِيَّةِ مَا شَاءَ اللهُ أَنْ يَكْتُبَ، وَكَانَ شَيْخًا كَبِيرًا قَدْ عَمِيَ، فَقَالَتْ لَهُ خَدِيجَةُ: أَيْ عَمِّ، اسْمَعْ مِنِ ابْنِ أَخِيكَ. قَالَ وَرَقَةُ بْنُ نَوْفَلٍ: يَا ابْنَ أَخِي، مَاذَا تَرَى فَأَخْبَرَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَبَرَ مَا رَآهُ، فَقَالَ لَهُ وَرَقَةُ: هَذَا النَّامُوسُ الَّذِي أُنْزِلَ عَلَى مُوسَى صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، يَا لَيْتَنِي فِيهَا جَذَعًا، يَا لَيْتَنِي أَكُونُ حَيًّا حِينَ يُخْرِجُكَ قَوْمُكَ. قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَوَ مُخْرِجِيَّ هُمْ؟". قَالَ وَرَقَةُ: نَعَمْ، لَمْ يَأْتِ رَجُلٌ قَطُّ بِمَا جِئْتَ بِهِ إِلَّا عُودِيَ، وَإِنْ يُدْرِكْنِي يَوْمُكَ أَنْصُرْكَ نَصْرًا مُؤَزَّرًا. وَفِي رِوَايَةٍ (لِلْبُخَارِيِّ): ثُمَّ لَمْ يَنْشَبْ وَرَقَةُ أَنْ تُوُفِّيَ وَفَتَرَ الْوَحْيُ. (ق)', 'ആഇശ(റ): നബി(സ)ക്ക് പ്രാരംഭത്തിൽ ലഭിച്ച ദിവ്യസന്ദേശങ്ങളുടെ തുടക്കം ഉറക്കത്തിൽ ദൃശ്യമാകുന്ന നല്ല സ്വപ്നങ്ങളായിരുന്നു. പ്രവാചകൻ(സ) കാണുന്ന എല്ലാ സ്വപ്നങ്ങളും പ്രഭാതോദയം പോലെ സ്പഷ്ടമായി പുലർന്നുകൊണ്ടിരുന്നു. പിന്നീട് ഏകാന്തവാസം പ്രവാചകർ(സ)ക്ക് പ്രിയങ്കരമായി തോന്നി. ഹിറാ ഗുഹയിലാണ് ഏകാന്തവാസമനുഷ്ഠിച്ചിരുന്നത്. കുറേ നാളുകൾക്കുള്ള ആഹാരപദാർത്ഥവുമായി ഗുഹയിൽ പോകും. അഥവാ, കുറെ രാത്രി ആരാധനയിൽ മുഴുകി അവിടെ കഴിച്ചുകൂട്ടും. പിന്നീട് ഖദീജ(റ)യുടെ അടുക്കലേക്ക് തിരിച്ചുവരും. വീണ്ടും ആഹാര പദാർത്ഥങ്ങൾ തയ്യാറാക്കികൊണ്ടു പോകും. ഹിറാ ഗുഹയിൽ വെച്ച് നബി(സ)ക്ക് സത്യം വന്നുകിട്ടുന്നതുവരെ ഈ നില തുടർന്നുപോന്നു. അങ്ങനെ മലക്ക് നബിയുടെ മുമ്പിൽ പ്രത്യക്ഷപ്പെട്ടു "ഓതുക" എന്നു പറഞ്ഞു: "ഞാൻ ഓതുന്നവനല്ല". നബി(സ) മറുപടി നൽകി. നബി(സ) പറയുന്നു: "അപ്പോൾ മലക്ക് എന്നെ പിടിച്ച് ശക്തിയായി ആശ്ലേഷിച്ചു. എനിക്ക് വളരെ വിഷമം അനുഭവപ്പെട്ടു. അനന്തരം എന്നെ വിട്ട് വീണ്ടും "ഓതുക" എന്നു കൽപിച്ചു. ഞാൻ ഓതുന്നവനല്ലെന്ന് അപ്പോഴും മറുപടി നൽകി. മലക്ക് എന്നെ പിടിച്ച് ശക്തിയോടെ വീണ്ടും ആശ്ലേഷിച്ചു. എനിക്ക് വളരെ വിഷമം തോന്നി. പിന്നെ എന്നെ വിട്ടശേഷം "ഓതുക" എന്നു പറഞ്ഞു. ഞാൻ ഓതുന്നവനല്ലെന്നു വീണ്ടും പറഞ്ഞപ്പോൾ മൂന്നാമത്തെ പ്രാവശ്യവും എനിക്ക് വിഷമം തോന്നുംവിധം മലക്ക് എന്നെ പിടിച്ച് ശക്തിയോടെ ആശ്ലേഷിച്ചു. അനന്തരം എന്നെ വിട്ട് പറഞ്ഞു: "സൃഷ്ടിച്ചവനായ നിന്റെ രക്ഷിതാവിന്റെ നാമത്തിൽ ഓതുക. മനുഷ്യനെ അവൻ ഭ്രൂണത്തിൽ നിന്ന് സൃഷ്ടിച്ചിരിക്കുന്നു. നീ വായിക്കുക. നിന്റെ രക്ഷിതാവ് അത്യുദാരനത്രെ. പേന കൊണ്ട് പഠിപ്പിച്ചവൻ. മനുഷ്യനെ അവന്ന് അറിയാത്തത് അവൻ പഠിപ്പിച്ചു".
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=8 and h.hadith_no=2), 1, 'وَفِي رِوَايَةٍ (لِلْبُخَارِيِّ): ثُمَّ لَمْ يَنْشَبْ وَرَقَةُ أَنْ تُوُفِّيَ وَفَتَرَ الْوَحْيُ. (ق)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى دُنْيَا يُصِيبُهَا، أَوْ إِلَى امْرَأَةٍ يَنْكِحُهَا، فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ. (ق)', 'ഉമർ(റ): പ്രവാചകൻ(സ) ഇപ്രകാരം പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്: നിശ്ചയം മനുഷ്യന്റെ കർമ്മങ്ങൾ അവയുടെ ഉദ്ദേശ്യങ്ങൾക്കനുസൃതമായി മാത്രമാണ് പരിഗണിക്കപ്പെടുക. ഓരോ മനുഷ്യനും (തന്റെ പ്രവർത്തനങ്ങൾക്ക് പ്രതിഫലമായി) ലഭിക്കുക അവനുദ്ദേശിച്ചത് മാത്രമായിരിക്കും. ഒരുത്തൻ പലായനം ചെയ്യുന്നത് ഭൗതിക നേട്ടങ്ങൾ കൈവരിക്കുവാനോ ഒരു സ്ത്രീയെ വിവാഹം ചെയ്യുവാനോ ഉദ്ദേശിച്ചുകൊണ്ടാണെങ്കിൽ അവന് തന്റെ പലായനം കൊണ്ട് ലഭിക്കുക അതു മാത്രമായിരിക്കും. (ബു,മു)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമർ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 73, 73, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ جَابِرِ بْنِ عَبْدِاللهِ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُمَا، وَهُوَ يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْيِ فَقَالَ فِي حَدِيثِهِ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "بَيْنَا أَنَا أَمْشِي إِذْ سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ، فَرَفَعْتُ بَصَرِي، فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ جَالِسٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالْأَرْضِ، فَرُعِبْتُ مِنْهُ فَرَجَعْتُ، فَقُلْتُ: زَمِّلُونِي زَمِّلُونِي. فَأَنْزَلَ اللهُ تَعَالَى: {يَا أَيُّهَا الْمُدَّثِّرُ قُمْ فَأَنْذِرْ} إِلَى قَوْلِهِ {وَالرُّجْزَ فَاهْجُرْ} فَحَمِيَ الْوَحْيُ وَتَتَابَعَ. (ق,ت)', 'ജാബിർ(റ): അദ്ദേഹം ദിവ്യസന്ദേശം നിലച്ച കാലത്തെക്കുറിച്ച് സംസാരിക്കുകയായിരുന്നു. സംസാരമധ്യേ അദ്ദേഹം പ്രവാചകൻ(സ)യെ ഉദ്ധരിച്ച് പറഞ്ഞു: "ഞാൻ നടന്നുകൊണ്ടിരിക്കെ ആകാശത്തുനിന്ന് ഒരു ശബ്ദം കേട്ടു. ഞാൻ ദൃഷ്ടിയുയർത്തി. അപ്പോഴതാ ഹിറാ ഗുഹയിൽ എന്റെ അടുക്കൽ വന്ന മലക്ക് ആകാശ ഭൂമികൾക്കിടയിൽ ഒരു സിംഹാസനത്തിൽ ഉപവിഷ്ടനായിരിക്കുന്നു! അതുകണ്ട് എനിക്ക് ഭയം തോന്നി. പിന്നെ ഞാൻ വീട്ടിലേക്ക് മടങ്ങിച്ചെന്ന് പറഞ്ഞു: "എന്നെ പുതപ്പിച്ചു തരൂ, എന്നെ പുതപ്പിച്ചു തരൂ" അപ്പോൾ: (ഓ, പുതച്ചു മൂടിയവനേ എഴുന്നേൽക്കുക, എന്നിട്ട് താക്കീത് നൽകുക, നിന്റെ രക്ഷിതാവിന്റെ മഹത്വം പ്രകീർത്തനം ചെയ്യുക. നിന്റെ വസ്ത്രം ശുദ്ധിയാക്കുക, അഴുക്കുകൾ വെടിയുക) എന്ന വചനങ്ങൾ അല്ലാഹു അവതരിപ്പിച്ചു. പിന്നീട് ദിവ്യസന്ദേശങ്ങൾക്ക് ചൂടുപിടിക്കുകയും തുടർച്ചയായി വരികയും ചെയ്തു." (ബു,മു,തു)', 'جَابِرِ بْنِ عَبْدِاللهِ الْأَنْصَارِيِّ', 'ജാബിർ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 73, 73, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَأَلَ الْحَارِثُ بْنُ هِشَامٍ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: كَيْفَ يَأْتِيكَ الْوَحْيُ؟ قَالَ: "فِي مِثْلِ صَلْصَلَةِ الْجَرَسِ، فَيُفْصَمُ عَنِّي وَقَدْ وَعَيْتُ عَنْهُ، وَهُوَ أَشَدُّهُ عَلَيَّ، وَأَحْيَانًا يَأْتِينِي فِي مِثْلِ صُورَةِ الْفَتَى فَيَنْبِذُهُ إِلَيَّ". (ن)', 'ആഇശ(റ): ഹാരിസുബ്നു ഹിശാം തിരുമേനി(സ)യോട് ചോദിച്ചു. താങ്കൾക്ക് എപ്രകാരമാണ് വഹ്യ് ലഭിക്കുക? തിരുമേനി(സ) പറഞ്ഞു: "ചിലപ്പോൾ മണിനാദം പോലെ അതു ലഭിക്കും ഞാനതു ഗ്രഹിച്ചു കഴിഞ്ഞാൽ അതു നിലക്കും, ആ രീതിയിൽ വഹ്യ് ലഭിക്കുന്നതാകട്ടെ എനിക്കു ഏറ്റവും കഠിനമായതാണ്. മറ്റു ചിലപ്പോൾ (മാലാഖ) മനുഷ്യരൂപത്തിൽ വന്ന് എനിക്ക് അതു കേൾപ്പിച്ചു തരും (അങ്ങനെ ഞാനതു ഗ്രഹിക്കും)." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 73, 73, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ يَحْيَى رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ أَبَا سَلَمَةَ بْنَ عَبْدِالرَّحْمَنِ: أَيُّ الْقُرْآنِ أُنْزِلَ قَبْلُ؟ قَالَ: {يَا أَيُّهَا الْمُدَّثِّرُ} فَقُلْتُ: أَوِ اقْرَأْ؟ فَقَالَ: سَأَلْتُ جَابِرَ بْنَ عَبْدِاللهِ رَضِيَ اللهُ عَنْهُمَا: أَيُّ الْقُرْآنِ أُنْزِلَ قَبْلُ؟ قَالَ: {يَا أَيُّهَا الْمُدَّثِّرُ} فَقُلْتُ: أَوِ اقْرَأْ؟ قَالَ جَابِرٌ: أُحَدِّثُكُمْ مَا حَدَّثَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "جَاوَرْتُ بِحِرَاءٍ شَهْرًا، فَلَمَّا قَضَيْتُ جِوَارِي نَزَلْتُ فَاسْتَبْطَنْتُ بَطْنَ الْوَادِي، فَنُودِيتُ فَنَظَرْتُ أَمَامِي وَخَلْفِي وَعَنْ يَمِينِي وَعَنْ شِمَالِي، فَلَمْ أَرَ أَحَدًا، ثُمَّ نُودِيتُ، فَنَظَرْتُ فَلَمْ أَرَ أَحَدًا، ثُمَّ نُودِيتُ فَرَفَعْتُ رَأْسِي، فَإِذَا هُوَ عَلَى الْعَرْشِ فِي الْهَوَاءِ يَعْنِي جِبْرِيلَ عَلَيْهِ السَّلَامُ، فَأَخَذَتْنِي رَجْفَةٌ شَدِيدَةٌ، فَأَتَيْتُ خَدِيجَةَ فَقُلْتُ: "دَثِّرُونِي" فَدَثَّرُونِي وَصَبُّوا عَلَيَّ مَاءً، فَأَنْزَلَ اللهُ عَزَّ وَجَلَّ: {يَا أَيُّهَا الْمُدَّثِّرُ، قُمْ فَأَنْذِرْ، وَرَبَّكَ فَكَبِّرْ، وَثِيَابَكَ فَطَهِّرْ}". (م)', 'യഹ്യ(റ): ഞാൻ അബൂസലമ(റ)യോട് ചോദിച്ചു. ഖുർആനിൽ ഏതാണ് ആദ്യമവതരിച്ചത്? അദ്ദേഹം പറഞ്ഞു: يا أيها المدثر എന്നതാണ്.¹ ഞാൻ ചോദിച്ചു: അതോ ''ഇഖ്റഅ്'' ആണോ? അദ്ദേഹം പറഞ്ഞു: ഇക്കാര്യം ഞാൻ ജാബിർ(റ)നോട് ചോദിച്ചിരുന്നു. يا أيها المدثر എന്നാണദ്ദേഹം പറഞ്ഞത്. അതോ ''ഇഖ്റഅ്'' ആണോ എന്ന് ഞാൻ സംശയം ചോദിച്ചപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഞങ്ങൾക്ക് റസൂൽ(സ) പറഞ്ഞു തന്നതാണ് ഞാൻ നിങ്ങൾക്ക് പറഞ്ഞു തരുന്നത്. നബി(സ) പറഞ്ഞു: "ഹിറയിൽ ഒരുമാസം ഞാൻ ധ്യാനനിരതനായി ഇരുന്നു. എന്റെ ധ്യാനം കഴിഞ്ഞപ്പോൾ ഞാൻ പുറത്ത് വന്നു ബത്നുൽ വാദിയിലേക്കിറങ്ങിച്ചെന്നു. അപ്പോൾ എന്നെ ആരോ വിളിച്ചു. ഞാൻ മുന്നോട്ടും പിന്നോട്ടും ഇടത്തോട്ടും വലത്തോട്ടും തിരിഞ്ഞു നോക്കി. എന്നാൽ ഞാനാരെയും കണ്ടില്ല. പിന്നെയും എന്നെ ആരോ വിളിച്ചു. ഞാൻ നോക്കിയപ്പോൾ ആരെയും കണ്ടില്ല. വീണ്ടും എന്നെ ആരോ വിളിച്ചു. ഞാൻ തലയുയർത്തി നോക്കിയപ്പോഴതാ അദ്ദേഹം അന്തരീക്ഷത്തിൽ. (നബി(സ) ഉദ്ദേശിച്ചത് ജിബ്രീൽ(അ)മിനെയാണ്) എനിക്ക് ശക്തിയായ വിറയൽ ബാധിച്ചു. ഞാൻ ഖദീജയുടെ അടുക്കൽ ചെന്ന് പറഞ്ഞു: "പുതപ്പിച്ചു തരൂ. അപ്പോൾ അവരെന്നെ പുതപ്പിച്ചു. അവരെന്റെ ശരീരത്തിൽ വെള്ളം തളിച്ചു. അപ്പോൾ (ഓ പുതപ്പിട്ടു മൂടിയവനേ, എഴുന്നേൽക്കുക, മുന്നറിയിപ്പു നൽകുക, നിന്റെ രക്ഷിതാവിന്റെ മഹത്വം പ്രകീർത്തനം ചെയ്യുക, നിന്റെ വസ്ത്രം ശുചിയാക്കി വെക്കുക) എന്ന വചനങ്ങൾ അല്ലാഹു അവതരിപ്പിച്ചു." (മു)', 'يَحْيَى', 'യഹ്യ(റ)', '¹. ഹിറാ ഗുഹയിൽ നിന്നു ലഭിച്ചത് "ഇഖ്റഅ്" ആണ്, ഗുഹയിൽ നിന്നു പുറത്ത് വന്ന ശേഷം ആദ്യമായി ലഭിച്ചത് يا أيها المدثر ആണെന്നാണുദ്ദേശ്യം.', null, array['م']::text[], array['മു']::text[], null, null, 73, 74, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ: فِي قَوْلِهِ تَعَالَى: {لَا تُحَرِّكْ بِهِ لِسَانَكَ لِتَعْجَلَ بِهِ} قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُعَالِجُ مِنَ التَّنْزِيلِ شِدَّةً، وَكَانَ مِمَّا يُحَرِّكُ شَفَتَيْهِ- فَقَالَ ابْنُ عَبَّاسٍ: فَأَنَا أُحَرِّكُهُمَا لَكُمْ كَمَا كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُحَرِّكُهُمَا، وَقَالَ سَعِيدٌ: أَنَا أُحَرِّكُهُمَا كَمَا رَأَيْتُ ابْنَ عَبَّاسٍ يُحَرِّكُهُمَا، فَحَرَّكَ شَفَتَيْهِ – فَأَنْزَلَ اللهُ تَعَالَى: {لَا تُحَرِّكْ بِهِ لِسَانَكَ لِتَعْجَلَ بِهِ، إِنَّ عَلَيْنَا جَمْعَهُ وَقُرْآنَهُ} قَالَ: جَمْعُهُ لَكَ فِي صَدْرِكَ وَتَقْرَأَهُ {فَإِذَا قَرَأْنَاهُ فَاتَّبِعْ قُرْآنَهُ} قَالَ: فَاسْتَمِعْ لَهُ وَأَنْصِتْ {ثُمَّ إِنَّ عَلَيْنَا بَيَانَهُ} ثُمَّ إِنَّ عَلَيْنَا أَنْ تَقْرَأَهُ، فَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعْدَ ذَلِكَ إِذَا أَتَاهُ جِبْرِيلُ اسْتَمَعَ، فَإِذَا انْطَلَقَ جِبْرِيلُ قَرَأَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَمَا قَرَأَهُ. (ق,ن)', 'ഇബ്നു അബ്ബാസ്(റ): "ഖുർആൻ അതിവേഗം ഹൃദിസ്ഥമാക്കാൻ അതിന്റെ വാക്കുകളാൽ നാവ് അനക്കിക്കൊണ്ടിരിക്കേണ്ടതില്ല" എന്ന സൂക്തത്തിന്റെ വിശദീകരണത്തിൽ അദ്ദേഹം പറഞ്ഞു: "ദിവ്യസന്ദേശം അവതരിക്കുമ്പോൾ നബി(സ) വളരെ ക്ലേശം അനുഭവിച്ചിരുന്നു. അവിടുന്ന് രണ്ടു ചുണ്ടുകളും അനക്കിക്കൊണ്ടിരുന്നു. ഇബ്നു അബ്ബാസ്(റ) പറഞ്ഞു: നബി(സ) ചുണ്ടനക്കിയതുപോലെ ഞാനും എന്റെ രണ്ടു ചുണ്ടുകളും അനക്കിക്കാണിക്കാം. (നിവേദകരിൽപെട്ട) സഈദ് പറഞ്ഞു: ഇബ്നു അബ്ബാസ്(റ) ഇളക്കിയത് ഞാൻ കണ്ടതുപോലെ ഞാനും അവ ഇളക്കിക്കാണിക്കാം. എന്നിട്ട് അദ്ദേഹും തന്റെ രണ്ടു ചുണ്ടുകളും ഇളക്കി. അപ്പോൾ ''ഖുർആൻ വേഗം മനഃപാഠമാക്കാൻ വേണ്ടി നീ നിന്റെ നാവ് ഇളക്കിക്കൊണ്ടിരിക്കേണ്ടതില്ല. അത് ക്രോഡീകരിക്കേണ്ടതിന്റെയും പാരായണം ചെയ്യേണ്ടതിന്റെയും ചുമതല നമുക്കാണ്'' എന്ന ഖുർആൻ സൂക്തം അല്ലാഹു അവതരിപ്പിച്ചു. ഇബ്നു അബ്ബാസ്(റ) പറഞ്ഞു: ക്രോഡീകരിക്കുക എന്നാൽ നിന്റെ ഹൃദയത്തിൽ അത് ക്രോഡീകരിക്കുകയും അങ്ങനെ നീ അത് ഓതുകയും ചെയ്യുക എന്നാണ്. ''അതു നാം ഓതിയാൽ അതിന്റെ പാരായണം നീ പിൻപറ്റുക'' എന്ന ആയത്തിനെ അദ്ദേഹം വിശദീകരിച്ചത്, അത് നീ നിശ്ശബ്ദത പാലിച്ച് ശ്രദ്ധിക്കുക എന്നാണ്. ''പിന്നെ അതിന്റെ വിശദീകരണം നമ്മുടെ കടമയാണ്.'' അഥവാ പിന്നീട് അത് നീ പാരായണം ചെയ്യലും നമ്മുടെ കടമയാണ്. അതിനുശേഷം ജിബ്രീൽ(അ) വന്നാൽ നബി(സ) ശ്രദ്ധിച്ചു കേൾക്കുകയും ജിബ്രീൽ(അ) പോയിക്കഴിഞ്ഞാൽ ജിബ്രീൽ(അ) പാരായണം ചെയ്തപോലെ പാരായണം ചെയ്യുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ബു,മു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നു അബ്ബാസ്(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 74, 75, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَجْوَدَ النَّاسِ، وَكَانَ أَجْوَدُ مَا يَكُونُ فِي رَمَضَانَ حِينَ يَلْقَاهُ جِبْرِيلُ، وَكَانَ يَلْقَاهُ فِي كُلِّ لَيْلَةٍ مِنْ رَمَضَانَ، فَيُدَارِسُهُ الْقُرْآنَ، فَلَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَجْوَدُ بِالْخَيْرِ مِنَ الرِّيحِ الْمُرْسَلَةِ. (ق,ن)', 'ഇബ്നു അബ്ബാസ്(റ): പ്രവാചകൻ(സ) ജനങ്ങളിൽ ഏറ്റവും ഉദാരനായിരുന്നു. ജിബ്രീൽ(അ) അവിടത്തെ സന്ദർശിക്കാറുള്ള റമദാൻ മാസത്തിലാണ് പ്രവാചകൻ(സ) ഏറ്റവും ഔദാര്യം പ്രകടിപ്പിച്ചിരുന്നത്. ജിബ്രീൽ(അ) റമദാനിലെ എല്ലാ രാത്രികളിലും പ്രവാചകൻ(സ)യെ സന്ദർശിക്കുകയും ഖുർആൻ അന്യോന്യം ഓതി കേൾപ്പിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. അടിച്ചു വീശുന്ന കാറ്റിനേക്കാൾ ഉദാരനത്രെ പ്രവാചകൻ(സ). (ബു,മു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നു അബ്ബാസ്(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 75, 75, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَنَّ أَبَا سُفْيَانَ بْنَ حَرْبٍ أَخْبَرَهُ أَنَّ هِرَقْلَ أَرْسَلَ إِلَيْهِ فِي رَكْبٍ مِنْ قُرَيْشٍ، وَكَانُوا تُجَّارًا بِالشَّأْمِ فِي الْمُدَّةِ الَّتِي كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَادَّ فِيهَا أَبَا سُفْيَانَ وَكُفَّارَ قُرَيْشٍ، فَأَتَوْهُ وَهُمْ بِإِيلِيَاءَ فَدَعَاهُمْ فِي مَجْلِسِهِ، وَحَوْلَهُ عُظَمَاءُ الرُّومِ، ثُمَّ دَعَاهُمْ وَدَعَا بِتَرْجُمَانِهِ فَقَالَ: أَيُّكُمْ أَقْرَبُ نَسَبًا بِهَذَا الرَّجُلِ الَّذِي يَزْعُمُ أَنَّهُ نَبِيٌّ؟ فَقَالَ أَبُو سُفْيَانَ: فَقُلْتُ: أَنَا أَقْرَبُهُمْ نَسَبًا، فَقَالَ: أَدْنُوهُ مِنِّي، وَقَرِّبُوا أَصْحَابَهُ، فَاجْعَلُوهُمْ عِنْدَ ظَهْرِهِ، ثُمَّ قَالَ لِتَرْجُمَانِهِ: قُلْ لَهُمْ: إِنِّي سَائِلٌ هَذَا عَنْ هَذَا الرَّجُلِ، فَإِنْ كَذَبَنِي فَكَذِّبُوهُ، فَوَاللهِ لَوْلَا الْحَيَاءُ مِنْ أَنْ يَأْثِرُوا عَلَيَّ كَذِبًا لَكَذَبْتُ عَنْهُ، ثُمَّ كَانَ أَوَّلَ مَا سَأَلَنِي عَنْهُ أَنْ قَالَ: كَيْفَ نَسَبُهُ فِيكُمْ؟ قُلْتُ: هُوَ فِينَا ذُو نَسَبٍ، قَالَ: فَهَلْ قَالَ هَذَا الْقَوْلَ مِنْكُمْ أَحَدٌ قَطُّ قَبْلَهُ؟ قُلْتُ: لَا، قَالَ: فَهَلْ كَانَ مِنْ آبَائِهِ مِنْ مَلِكٍ؟ قُلْتُ: لَا، قَالَ: فَأَشْرَافُ النَّاسِ يَتَّبِعُونَهُ أَمْ ضُعَفَاؤُهُمْ؟ فَقُلْتُ: بَلْ ضُعَفَاؤُهُمْ، قَالَ: أَيَزِيدُونَ أَمْ يَنْقُصُونَ؟ قُلْتُ: بَلْ يَزِيدُونَ، قَالَ: فَهَلْ يَرْتَدُّ أَحَدٌ مِنْهُمْ سَخْطَةً لِدِينِهِ بَعْدَ أَنْ يَدْخُلَ فِيهِ؟ قُلْتُ: لَا، قَالَ: فَهَلْ كُنْتُمْ تَتَّهِمُونَهُ بِالْكَذِبِ قَبْلَ أَنْ يَقُولَ مَا قَالَ؟ قُلْتُ: لَا، قَالَ: فَهَلْ يَغْدِرُ؟ قُلْتُ: لَا، وَنَحْنُ مِنْهُ فِي مُدَّةٍ لَا نَدْرِي مَا هُوَ فَاعِلٌ فِيهَا- قَالَ: وَلَمْ تُمْكِنِّي كَلِمَةٌ أُدْخِلُ فِيهَا شَيْئًا غَيْرَ هَذِهِ الْكَلِمَةِ- قَالَ: فَهَلْ قَاتَلْتُمُوهُ؟ قُلْتُ: نَعَمْ. قَالَ: فَكَيْفَ كَانَ قِتَالُكُمْ إِيَّاهُ؟ قُلْتُ: الْحَرْبُ بَيْنَنَا وَبَيْنَهُ سِجَالٌ، يَنَالُ مِنَّا وَنَنَالُ مِنْهُ. قَالَ: مَاذَا يَأْمُرُكُمْ؟ قُلْتُ: يَقُولُ: اعْبُدُوا اللهَ وَحْدَهُ وَلَا تُشْرِكُوا بِهِ شَيْئًا، وَاتْرُكُوا مَا يَقُولُ آبَاؤُكُمْ، وَيَأْمُرُنَا بِالصَّلَاةِ، وَالزَّكَاةِ، وَالصِّدْقِ، وَالْعَفَافِ، وَالصِّلَةِ. فَقَالَ لِلتُّرْجُمَانِ: قُلْ لَهُ: سَأَلْتُكَ عَنْ نَسَبِهِ فَذَكَرْتَ أَنَّهُ فِيكُمْ ذُو نَسَبٍ، فَكَذَلِكَ الرُّسُلُ تُبْعَثُ فِي نَسَبِ قَوْمِهَا. وَسَأَلْتُكَ هَلْ قَالَ أَحَدٌ مِنْكُمْ هَذَا الْقَوْلَ فَذَكَرْتَ أَنْ لَا فَقُلْتُ لَوْ كَانَ أَحَدٌ قَالَ هَذَا الْقَوْلَ قَبْلَهُ لَقُلْتُ رَجُلٌ يَأْتِي بِقَوْلٍ قِيلَ قَبْلَهُ. وَسَأَلْتُكَ هَلْ كَانَ مِنْ آبَائِهِ مِنْ مَلِكٍ فَذَكَرْتَ أَنْ لَا. قُلْتُ فَلَوْ كَانَ مِنْ آبَائِهِ مِنْ مَلِكٍ قُلْتُ رَجُلٌ يَطْلُبُ مُلْكَ أَبِيهِ. وَسَأَلْتُكَ هَلْ كُنْتُمْ تَتَّهِمُونَهُ بِالْكَذِبِ قَبْلَ أَنْ يَقُولَ مَا قَالَ فَذَكَرْتَ أَنْ لَا. فَقَدْ أَعْرِفُ أَنَّهُ لَمْ يَكُنْ لِيَذَرَ الْكَذِبَ عَلَى النَّاسِ وَيَكْذِبَ عَلَى اللهِ. وَسَأَلْتُكَ أَشْرَافُ النَّاسِ اتَّبَعُوهُ أَمْ ضُعَفَاؤُهُمْ؟ فَذَكَرْتَ أَنَّ ضُعَفَاءَهُمُ اتَّبَعُوهُ، وَهُمْ أَتْبَاعُ الرُّسُلِ. وَسَأَلْتُكَ أَيَزِيدُونَ أَمْ يَنْقُصُونَ؟ فَذَكَرْتَ أَنَّهُمْ يَزِيدُونَ. وَكَذَلِكَ أَمْرُ الْإِيمَانِ حَتَّى يَتِمَّ. وَسَأَلْتُكَ أَيَرْتَدُّ أَحَدٌ سَخْطَةً لِدِينِهِ بَعْدَ أَنْ يَدْخُلَ فِيهِ؟ فَذَكَرْتَ أَنْ لَا. وَكَذَلِكَ الْإِيمَانُ حِينَ تُخَالِطُ بَشَاشَتُهُ الْقُلُوبَ. وَسَأَلْتُكَ هَلْ يَغْدِرُ؟ فَذَكَرْتَ أَنْ لَا. وَكَذَلِكَ الرُّسُلُ لَا تَغْدِرُ، وَسَأَلْتُكَ بِمَا يَأْمُرُكُمْ فَذَكَرْتَ أَنَّهُ يَأْمُرُكُمْ أَنْ تَعْبُدُوا اللهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا وَيَنْهَاكُمْ عَنْ عِبَادَةِ الْأَوْثَانِ وَيَأْمُرُكُمْ بِالصَّلَاةِ وَالصِّدْقِ وَالْعَفَافِ فَإِنْ كَانَ مَا تَقُولُ حَقًّا فَسَيَمْلِكُ مَوْضِعَ قَدَمَيَّ هَاتَيْنِ وَقَدْ كُنْتُ أَعْلَمُ أَنَّهُ خَارِجٌ لَمْ أَكُنْ أَظُنُّ أَنَّهُ مِنْكُمْ، فَلَوْ أَنِّي أَعْلَمُ أَنِّي أَخْلُصُ إِلَيْهِ لَتَجَشَّمْتُ لِقَاءَهُ، وَلَوْ كُنْتُ عِنْدَهُ لَغَسَلْتُ عَنْ قَدَمِهِ. ثُمَّ دَعَا بِكِتَابِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الَّذِي بَعَثَ بِهِ دِحْيَةُ إِلَى عَظِيمِ بُصْرَى، فَدَفَعَهُ إِلَى هِرَقْلَ فَقَرَأَهُ، فَإِذَا فِيهِ: بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ، مِنْ مُحَمَّدٍ عَبْدِ اللهِ وَرَسُولِهِ إِلَى هِرَقْلَ عَظِيمِ الرُّومِ، سَلَامٌ عَلَى مَنِ اتَّبَعَ الْهُدَى. أَمَّا بَعْدُ، فَإِنِّي أَدْعُوكَ بِدِعَايَةِ الْإِسْلَامِ، أَسْلِمْ تَسْلَمْ، يُؤْتِكَ اللهُ أَجْرَكَ مَرَّتَيْنِ فَإِنْ تَوَلَّيْتَ، فَإِنَّ عَلَيْكَ إِثْمَ الْأَرِيسِيِّينَ وَ{يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَى كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ أَنْ لَا نَعْبُدَ إِلَّا اللهَ وَلَا نُشْرِكَ بِهِ شَيْئًا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِنْ دُونِ اللهِ فَإِنْ تَوَلَّوْا فَقُولُوا اشْهَدُوا بِأَنَّا مُسْلِمُونَ} قَالَ أَبُو سُفْيَانَ: فَلَمَّا قَالَ مَا قَالَ وَفَرَغَ مِنْ قِرَاءَةِ الْكِتَابِ، كَثُرَ عِنْدَهُ الصَّخَبُ وَارْتَفَعَتِ الْأَصْوَاتُ، وَأُخْرِجْنَا، فَقُلْتُ لِأَصْحَابِي حِينَ أُخْرِجْنَا: لَقَدْ أَمِرَ أَمْرُ ابْنِ أَبِي كَبْشَةَ، إِنَّهُ يَخَافُهُ مَلِكُ بَنِي الْأَصْفَرِ، فَمَا زِلْتُ مُوقِنًا أَنَّهُ سَيَظْهَرُ حَتَّى أَدْخَلَ اللهُ عَلَيَّ الْإِسْلَامَ، وَكَانَ ابْنُ النَّاظُورِ صَاحِبُ إِيلِيَاءَ وَهِرَقْلَ أُسْقُفًّا عَلَى نَصَارَى الشَّأْمِ، يُحَدِّثُ أَنَّ هِرَقْلَ حِينَ قَدِمَ إِيلِيَاءَ أَصْبَحَ يَوْمًا خَبِيثَ النَّفْسِ، فَقَالَ بَعْضُ بَطَارِقَتِهِ: قَدِ اسْتَنْكَرْنَا هَيْئَتَكَ، قَالَ ابْنُ النَّاظُورِ: وَكَانَ هِرَقْلُ حَزَّاءً يَنْظُرُ فِي النُّجُومِ، فَقَالَ لَهُمْ حِينَ سَأَلُوهُ: إِنِّي رَأَيْتُ اللَّيْلَةَ حِينَ نَظَرْتُ فِي النُّجُومِ مَلِكَ الْخِتَانِ قَدْ ظَهَرَ، فَمَنْ يَخْتَتِنُ مِنْ هَذِهِ الْأُمَّةِ؟ قَالُوا: لَيْسَ يَخْتَتِنُ إِلَّا الْيَهُودُ، فَلَا يُهِمَّنَّكَ شَأْنُهُمْ، وَاكْتُبْ إِلَى مَدَايِنِ مُلْكِكَ فَيَقْتُلُوا مَنْ فِيهِمْ مِنَ الْيَهُودِ، فَبَيْنَمَا هُمْ عَلَى أَمْرِهِمْ أُتِيَ هِرَقْلُ بِرَجُلٍ أَرْسَلَ بِهِ مَلِكُ غَسَّانَ، يُخْبِرُ عَنْ خَبَرِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا اسْتَخْبَرَهُ هِرَقْلُ قَالَ: اذْهَبُوا فَانْظُرُوا أَمُخْتَتِنٌ هُوَ أَمْ لَا؟ فَنَظَرُوا إِلَيْهِ فَحَدَّثُوهُ أَنَّهُ مُخْتَتِنٌ، وَسَأَلَهُ عَنِ الْعَرَبِ، فَقَالَ: هُمْ يَخْتَتِنُونَ، فَقَالَ هِرَقْلُ: هَذَا مُلْكُ هَذِهِ الْأُمَّةِ قَدْ ظَهَرَ، ثُمَّ كَتَبَ هِرَقْلُ إِلَى صَاحِبٍ لَهُ بِرُومِيَةَ، وَكَانَ نَظِيرَهُ فِي الْعِلْمِ، وَسَارَ هِرَقْلُ إِلَى حِمْصَ، فَلَمْ يَرِمْ حِمْصَ حَتَّى أَتَاهُ كِتَابٌ مِنْ صَاحِبِهِ يُوَافِقُ رَأْيَ هِرَقْلَ عَلَى خُرُوجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَنَّهُ نَبِيٌّ، فَأَذِنَ هِرَقْلُ لِعُظَمَاءِ الرُّومِ فِي دَسْكَرَةٍ لَهُ بِحِمْصَ، ثُمَّ أَمَرَ بِأَبْوَابِهَا فَغُلِّقَتْ، ثُمَّ اطَّلَعَ، فَقَالَ: يَا مَعْشَرَ الرُّومِ، هَلْ لَكُمْ فِي الْفَلَاحِ وَالرُّشْدِ وَأَنْ يَثْبُتَ مُلْكُكُمْ؟ فَتُبَايِعُوا هَذَا النَّبِيَّ، فَحَاصُوا حَيْصَةَ حُمُرِ الْوَحْشِ إِلَى الْأَبْوَابِ، فَوَجَدُوهَا قَدْ غُلِّقَتْ، فَلَمَّا رَأَى هِرَقْلُ نَفْرَتَهُمْ وَأَيِسَ مِنَ الْإِيمَانِ قَالَ: رُدُّوهُمْ عَلَيَّ، وَقَالَ: إِنِّي قُلْتُ مَقَالَتِي آنِفًا أَخْتَبِرُ بِهَا شِدَّتَكُمْ عَلَى دِينِكُمْ، فَقَدْ رَأَيْتُ، فَسَجَدُوا لَهُ وَرَضُوا عَنْهُ، فَكَانَ ذَلِكَ آخِرَ شَأْنِ هِرَقْلَ. (ق)', 'ഇബ്നു അബ്ബാസ്(റ): അദ്ദേഹത്തോട് അബൂസുഫ്യാൻ പറഞ്ഞു: അദ്ദേഹം (അബൂസുഫ്യാൻ) ശാമിലെ കച്ചവടക്കാരായ ഒരു ഖുറൈശീ സംഘത്തിലായിരിക്കെ ഹിർഖൽ രാജാവ് കൊട്ടാരത്തിലേക്ക് അദ്ദേഹത്തെ ക്ഷണിച്ചു. അന്ന് നബി(സ) അബൂസുഫ്യാനും ഖുറൈശികളായ സത്യനിഷേധികളുമായി (ഹുദൈബിയ) സന്ധിയിലായിരുന്നു. അവർ ഈലിയാഇലായിരിക്കെ ഹിർഖലിന്റെ അടുത്ത് ചെന്നു. ഹിർഖൽ അവരെ ദർബാറിലേക്ക് ക്ഷണിച്ചു. അദ്ദേഹത്തിനുചുറ്റും റോമിലെ പ്രമാണിമാരുണ്ടായിരുന്നു. ഹിർഖൽ അവരെയും പരിഭാഷകനെയും വിളിച്ചു. എന്നിട്ട് ചോദിച്ചു. നബിയാണെന്ന് വാദിക്കുന്ന ആ മനുഷ്യനുമായി നിങ്ങളിൽ ഏറ്റവും അടുത്ത കുടുംബ ബന്ധമുള്ളവനാരാണ്? ഞാൻ പറഞ്ഞു: ഞാനാണ് അവരിൽ ഏറ്റവും അടുത്ത ബന്ധമുള്ളവൻ. ഹിർഖൽ കൽപ്പിച്ചു: അവനെ എന്നോട് അടുപ്പിക്കുക! അവന്റെ ആളുകളെ അവന്റെ പിന്നിൽ അടുപ്പിച്ചു നിർത്തുക! പിന്നെ അദ്ദേഹം തന്റെ പരിഭാഷകനോട് പറഞ്ഞു: ഞാൻ ആ മനുഷ്യനെക്കുറിച്ച് ചിലതെല്ലാം ചോദിക്കുകയാണെന്ന് നീ അവരോട് പറയുക. അവൻ (അബൂസുഫ്യാൻ) കളവു പറഞ്ഞാൽ അവനെ നിങ്ങൾ അസത്യപ്പെടുത്തുക. (അബൂ സുഫ്യാൻ പറയുന്നു: അല്ലാഹുവാണ, അവരെന്റെമേൽ കള്ളമാരോപിക്കുമെന്ന വിഷയത്തിൽ എനിക്ക് നാണം തോന്നിയിട്ടില്ലെങ്കിൽ ഞാൻ കളവ് പറഞ്ഞേനെ). ഹിർഖൽ ആദ്യമായി എന്നോട് ചോദിച്ചു: നിങ്ങളിൽ മുഹമ്മദിന്റെ കുടുംബ നിലവാരമെങ്ങനെയാണ്? ഞാൻ പറഞ്ഞു: അദ്ദേഹം ഞങ്ങളിൽ ഉയർന്ന കുടുംബത്തിൽ പെട്ടവനാണ്. അദ്ദേഹം ചോദിച്ചു: നിങ്ങളിലാരെങ്കിലും ഇതിനുമുമ്പ് ഈ വാദം ഉന്നയിച്ചിട്ടുണ്ടോ? ഞാൻ പറഞ്ഞു: ഇല്ല. അദ്ദേഹം ചോദിച്ചു: അദ്ദേഹത്തിന്റെ പൂർവ്വ പിതാക്കളിലാരെങ്കിലും രാജാവായിരുന്നോ? ഞാൻ പറഞ്ഞു: ''ഇല്ല''. അദ്ദേഹം ചോദിച്ചു: ജനങ്ങളിൽ പൗരപ്രമുഖരോ അതോ ബലഹീനരോ അദ്ദേഹത്തെ പിൻപറ്റുന്നത്? ഞാൻ പറഞ്ഞു: ബലഹീനരാണ്. അദ്ദേഹം ചോദിച്ചു: അവരുടെ എണ്ണം കുറയുകയാണോ അതോ കൂടുകയാണോ? ഞാൻ പറഞ്ഞു: ''കൂടുകയാണ്''. അദ്ദേഹം ചോദിച്ചു: ആ മതത്തിൽ പ്രവേശിച്ചശേഷം അതിനോടുള്ള വെറുപ്പുമൂലം ആരെങ്കിലും അതിൽനിന്ന് പുറത്തു പോകുന്നുണ്ടോ? ഞാൻ പറഞ്ഞു: ഇല്ല. അദ്ദേഹം ചോദിച്ചു: ഈ വാദം പറയുന്നതിനുമുമ്പ് നിങ്ങൾ അദ്ദേഹത്തെക്കുറിച്ച് എന്തെങ്കിലും കളവ് പറയുന്നവനായി ആരോപിച്ചിരുന്നുവോ?ഞാൻപറഞ്ഞു: ''ഇല്ല''. അദ്ദേഹം ചോദിച്ചു: അദ്ദേഹം വഞ്ചിക്കുമോ? ഞാൻ പറഞ്ഞു: ''ഇല്ല'', ഞങ്ങൾ ഇപ്പോൾ അദ്ദേഹവുമായി ഒരു സന്ധിയിലാണ് അതിലിപ്പോൾ അദ്ദേഹം എന്താണ് ചെയ്യുക എന്ന് ഞങ്ങൾക്കറിയില്ല. (നബിയെ വില കുറച്ചുകാണിക്കാൻ ഈ വാക്കല്ലാതെ മറ്റൊന്നും പ്രയോഗിക്കാൻ എനിക്ക് കഴിഞ്ഞില്ല.) അദ്ദേഹം ചോദിച്ചു: നിങ്ങൾ അദ്ദേഹത്തോട് യുദ്ധം ചെയ്തിട്ടുണ്ടോ? ഞാൻ പറഞ്ഞു: ''ഉണ്ട്''. അദ്ദേഹം ചോദിച്ചു: നിങ്ങൾ അവരുമായി ചെയ്ത യുദ്ധം എങ്ങനെയായിരുന്നു? ഞാൻ പറഞ്ഞു: ''യുദ്ധത്തിൽ ഞങ്ങൾക്കും അവർക്കും വിജയ പരാജയങ്ങളുണ്ടായിട്ടുണ്ട്, ചിലപ്പോൾ അദ്ദേഹം വിജയിക്കും, മറ്റു ചിലപ്പോൾ ഞങ്ങളും''.അദ്ദേഹംചോദിച്ചു:അദ്ദേഹമെന്താണ് നിങ്ങളോട് കൽപ്പിക്കുന്നത്? ഞാൻ പറഞ്ഞു: അദ്ദേഹം പറയുന്നു: ''നിങ്ങൾ അല്ലാഹുവിനെ മാത്രം ആരാധിക്കുക, അവനിൽ ആരെയും പങ്ക് ചേർക്കാതിരിക്കുക, നിങ്ങളുടെ പൂർവ്വ പിതാക്കൾ ആരാധിച്ചവയെ നിങ്ങൾ ഉപേക്ഷിക്കുക, നിസ്കാരം, സകാത്ത്, സത്യസന്ധത, സദാചാരനിഷ്ഠ, കുടുംബബന്ധം ചേർക്കൽ എന്നിവയും അദ്ദേഹം ഞങ്ങളോട് കൽപിക്കുന്നു''. ഹിർഖൽ പരിഭാഷകനോട് പറഞ്ഞു: നീ അവനോട് പറയുക. ഞാൻ അദ്ദേഹത്തിന്റെ തറവാടിനെക്കുറിച്ച് നിങ്ങളോട് ചോദിച്ചു. നിങ്ങൾ പറഞ്ഞു: നിങ്ങളിൽ ഏറ്റവും നല്ല തറവാട്ടുകാരനാണദ്ദേഹം. അപ്രകാരം പ്രവാചകന്മാർ തങ്ങളുടെ ജനതയിലെ നല്ല തറവാട്ടിൽ നിന്നാണ് നിയോഗിക്കപ്പെടുക. അദ്ദേഹത്തിന്റെ മുമ്പ് നിങ്ങളിലാരെങ്കിലും ഈ വാദം ഉന്നയിച്ചിരുന്നോ എന്ന് ചോദിച്ചപ്പോൾ, നിങ്ങൾ ''ഇല്ല'' എന്നു പറഞ്ഞു. ഞാൻ പറയട്ടെ: തനിക്ക് മുമ്പ് ആരെങ്കിലും ഇത്തരമൊരു വാദമുന്നയിച്ചിട്ടുണ്ടെങ്കിൽ അതേറ്റുപറയുകയാണയാൾ എന്ന് ഞാൻ പറയുമായിരുന്നു. അദ്ദേഹത്തിന്റെ പൂർവ്വീകരിൽ ആരെങ്കിലും രാജാവായിരുന്നോ എന്ന് ചോദിച്ചപ്പോൾ നിങ്ങൾ ''ഇല്ല'' എന്ന് പറഞ്ഞു. അദ്ദേഹത്തിൻെറ പിതാക്കളിലാരെങ്കിലും രാജാവായിരുന്നെങ്കിൽ അദ്ദേഹം തന്റെ പിതാവിന്റെ ആധിപത്യം തേടുകയാണെന്ന് ഞാൻ പറയുമായിരുന്നു. അദ്ദേഹം ഇപ്പോൾ ഈ വാദം ഉന്നയിക്കുന്നതിനു മുമ്പ് നിങ്ങൾ അദ്ദേഹത്തിൽ കളവ് ആരോപിച്ചിരുന്നോ എന്ന് ഞാൻ ചോദിച്ചപ്പോൾ നിങ്ങൾ ''ഇല്ല'' എന്നു പറഞ്ഞു. ഞാൻ മനസ്സിലാക്കുന്നത് ജനങ്ങളുടെ കാര്യത്തിൽ കളവ് പറയാത്ത ഒരാൾക്ക് അല്ലാഹുവിന്റെ പേരിൽ കളവു പറയാൻ കഴിയുകയില്ല എന്നാണ്. ജനങ്ങളിൽ പ്രമാണിമാരോ അതോ പാവങ്ങളോ അദ്ദേഹത്തെ പിൻപറ്റുന്നതെന്ന് ഞാൻ നിങ്ങളോട് ചോദിച്ചു, പാവങ്ങളാണ് പിൻപറ്റുന്നതെന്ന് നിങ്ങൾ പറഞ്ഞു. യഥാർത്ഥത്തിൽ അവരാണ് ദൈവദൂതന്മാരുടെ അനുയായികൾ. അവർ കുറയുകയാണോ കൂടുകയാണോ എന്ന് ഞാൻ നിങ്ങളോട് ചോദിച്ചു. അവർ കൂടുകയാണെന്ന് നിങ്ങൾ പറഞ്ഞു. വിശ്വാസത്തിന്റെ കാര്യം അത് പൂർത്തിയാകുന്നതുവരെ അങ്ങനെയാണ്. അവർ അവരുടെ ദീനിൽ പ്രവേശിച്ചശേഷം അതിനോടുള്ള വെറുപ്പ് മൂലം അതിൽ നിന്ന് പുറത്തു പോകുന്നുണ്ടോ എന്ന് നിങ്ങളോട് ഞാൻ ചോദിച്ചപ്പോൾ ഇല്ല എന്നു നിങ്ങൾ പറഞ്ഞു. സത്യവിശ്വാസത്തിന്റെ പ്രഭ ഹൃദയത്തിൽ ലയിച്ചു കഴിയുമ്പോൾ അതിന്റെ നിലപാട് അങ്ങിനെതന്നെയായിരിക്കും. അദ്ദേഹം വഞ്ചിക്കാറുണ്ടോ എന്ന് ഞാൻ നിങ്ങളോട് ചോദിച്ചു. ഇല്ലെന്ന് നിങ്ങൾ പറഞ്ഞു. പ്രവാചകന്മാർ വഞ്ചിക്കുകയില്ല. നിങ്ങളോട് എന്താണ് അദ്ദേഹം കൽപ്പിക്കുന്നതെന്ന് ഞാൻ ചോദിച്ചു. അല്ലാഹുവിനെ മാത്രം ആരാധിക്കണമെന്നും അവനിൽ യാതൊന്നിനേയും പങ്ക് ചേർക്കരുതെന്നും കൽപിക്കുന്നു. ബിംബാരാധന നിങ്ങൾക്ക് വിലക്കുന്നു. നിസ്കാരം, സത്യസന്ധത, സദാചാരനിഷ്ഠ എന്നിവ കൽപ്പിക്കുകയും ചെയ്യുന്നു എന്ന് നിങ്ങൾ പറഞ്ഞു. നിങ്ങൾ പറഞ്ഞത് സത്യമാണെങ്കിൽ എന്റെ ഈ രണ്ട് പാദങ്ങൾ സ്പർശിക്കുന്ന സ്ഥലം കൂടി അദ്ദേഹം അധീനപ്പെടുത്തും. അദ്ദേഹം വരുമെന്ന് ഞാനറിഞ്ഞിരുന്നു. എന്നാൽ അത് നിങ്ങളിൽ നിന്നായിരിക്കുമെന്ന് ഞാൻ ഊഹിച്ചിരുന്നില്ല. എനിക്ക് അദ്ദേഹത്തിന്റെ അടുക്കൽ എത്തിച്ചേരാൻ കഴിഞ്ഞിരുന്നെങ്കിൽ അദ്ദേഹത്തെ കാണാൻ എന്ത് സാഹസവും ഞാൻ കാണിക്കുമായിരുന്നു. അദ്ദേഹത്തിന്റെ അടുക്കൽ എത്തിച്ചേർന്നിരുന്നെങ്കിൽ അദ്ദേഹത്തിന്റെ പാദം ഞാൻ കഴുകിക്കൊടുക്കുമായിരുന്നു. പിന്നീട് ദിഹ്യ(റ)വിന്റെ² പക്കൽ ബുസ്റായിലെ ഭരണാധിപന് നബി(സ) അയച്ച കത്ത് കൊണ്ടുവരാൻ ഹിർഖൽ ആവശ്യപ്പെട്ടു. അദ്ദേഹം കത്ത് ഹിർഖലിനെ ഏൽപ്പിച്ചു. അയാൾ അത് വായിച്ചു. അതിൽ ഇപ്രകാരമായിരുന്നു: "പരമകാരുണികനും കരുണാനിധിയുമായ അല്ലാഹുവിന്റെ നാമത്തിൽ;അല്ലാഹുവിന്റെ അടിമയും ദൂതനുമായ മുഹമ്മദ് റോമിലെ രാജാവ് ഹിർഖലിന് (നൽകുന്ന സന്ദേശം). ശേഷം, സന്മാർഗം പിൻപറ്റിയവർക്ക് രക്ഷയുണ്ടാവട്ടെ. ഇസ്ലാമിന്റെ പ്രബോധനം മുഖേന ഞാൻ താങ്കളെ ക്ഷണിക്കുന്നു. മുസ്ലിമാകുക. എന്നാൽ താങ്കൾക്ക് രക്ഷപ്പെടാം. അല്ലാഹു താങ്കൾക്ക് രണ്ട് പ്രതിഫലം നൽകും. ഇനി താങ്കൾ പിന്തിരിയുകയാണെങ്കിൽ ആ കർഷകരുടെ³ പാപം കൂടി താങ്കൾ വഹിക്കേണ്ടിവരും വേദക്കാരെ! ഞങ്ങൾക്കും നിങ്ങൾക്കുമിടയിൽ തുല്യമായ ഒരു തത്വത്തിലേക്ക് നിങ്ങൾ വരിക. അതെന്തെന്നാൽ നാം അല്ലാഹുവിനെയല്ലാതെ ആരാധിക്കാതിരിക്കുകയും അവനിൽ ഒന്നിനേയും പങ്ക് ചേർക്കാതിരിക്കുകയും നമ്മിൽ ചിലർ മറ്റു ചിലരെ ആരാധ്യന്മാരാക്കാതിരിക്കുകയും ചെയ്യലാണ്. ഇനി അവർ പിന്തിരിയുകയാണെങ്കിൽ നിങ്ങളവരോട് പറയുക: ഞങ്ങൾ മുസ്ലിംകളാണെന്ന് നിങ്ങൾ സാക്ഷ്യം വഹിക്കുക."
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِنَّ اللهَ عَزَّ وَجَلَّ تَابَعَ الْوَحْيَ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَبْلَ وَفَاتِهِ حَتَّى تُوُفِّيَ، وَأَكْثَرُ مَا كَانَ الْوَحْيُ يَوْمَ تُوُفِّيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ق)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) ഇഹലോകം വെടിയുന്നതു വരെയും അല്ലാഹു തിരുനബി(സ)ക്ക് ദിവ്യബോധനം തുടർച്ചയായി അവതരിപ്പിച്ചു. ദിവ്യബോധനം ഏറ്റവും കൂടുതൽ അവതീർണ്ണമായത് പ്രവാചകൻ(സ) വഫാതായ ദിവസമായിരുന്നു. (ബു,മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 79, 79, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا أُنْزِلَ عَلَيْهِ الْوَحْيُ كُرِبَ لِذَلِكَ وَتَرَبَّدَ وَجْهُهُ. (م)', 'ഉബാദതുബ്നുസ്സ്വാമിത്(റ): നബി(സ)ക്ക് വഹ്യ് അവതരിക്കുമ്പോൾ അതുകാരണം അവിടുന്ന് പ്രയാസപ്പെടുകയും തിരുവദനം മൺവർണ്ണമാകുകയും ചെയ്യാറുണ്ടായിരുന്നു. (മു)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നുസ്സ്വാമിത്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 79, 79, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ صَفْوَانَ بْنِ يَعْلَى بْنِ أُمَيَّةَ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَنَّ يَعْلَى كَانَ يَقُولُ: لَيْتَنِي أَرَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ يُنْزَلُ عَلَيْهِ الْوَحْيُ، فَلَمَّا كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالْجِعْرَانَةِ وَعَلَيْهِ ثَوْبٌ قَدْ أُظِلَّ عَلَيْهِ، وَمَعَهُ فِيهِ نَاسٌ مِنْ أَصْحَابِهِ، إِذْ جَاءَهُ رَجُلٌ مُتَضَمِّخٌ بِطِيبٍ، فَقَالَ: يَا رَسُولَ اللهِ، كَيْفَ تَرَى فِي رَجُلٍ أَحْرَمَ فِي جُبَّةٍ بَعْدَمَا تَضَمَّخَ بِالطِّيبِ؟ فَنَظَرَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَاعَةً، فَجَاءَهُ الْوَحْيُ، فَأَشَارَ عُمَرُ إِلَى يَعْلَى بِيَدِهِ أَنْ تَعَالَ، فَجَاءَ يَعْلَى فَأَدْخَلَ رَأْسَهُ، فَإِذَا هُوَ مُحْمَرُّ الْوَجْهِ يَغِطُّ كَذَلِكَ سَاعَةً، ثُمَّ سُرِّيَ عَنْهُ فَقَالَ: "أَيْنَ الَّذِي يَسْأَلُنِي عَنِ الْعُمْرَةِ آنِفًا؟". فَالْتُمِسَ الرَّجُلُ فَجِيءَ بِهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "أَمَّا الطِّيبُ الَّذِي بِكَ فَاغْسِلْهُ ثَلَاثَ مَرَّاتٍ، وَأَمَّا الْجُبَّةُ فَانْزِعْهَا، ثُمَّ اصْنَعْ فِي عُمْرَتِكَ كَمَا تَصْنَعُ فِي حَجِّكَ". (ق)', 'സ്വഫ്വാനുബ്നു യഅ്ലബ്നു ഉമയ്യ(റ): നബി(സ)ക്ക് വഹ്യ് അവതരിക്കുന്ന രംഗം തനിക്ക് കാണിച്ചുതരാൻ യഅ്ല(റ) ഉമറി(റ)നോട് പറയുമായിരുന്നു. അങ്ങനെ, നബി(സ) ഒരു സംഘം അനുചരരോടൊപ്പം ജിഅ്റാനയിൽ ഇരിക്കുകയായിരുന്നു. അവിടന്ന് തണൽ കൊള്ളാനുള്ള ഒരു വസ്ത്രം ധരിച്ചിരുന്നു. അപ്പോൾ സുഗന്ധം പൂശിയ ഒരാൾ വന്നു ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ! സുഗന്ധം പുരട്ടിയ വസ്ത്രം ധരിച്ച് ഉംറക്ക് ഇഹ്റാം ചെയ്ത ഒരാളെ കുറിച്ച് താങ്കളെന്തു പറയുന്നു? നബി(സ) അൽപ സമയം ആലോചിച്ചു. തുടർന്ന് അവിടുത്തേക്ക് വഹ്യ് അവതരിച്ചു. അപ്പോൾ ഉമർ(റ) യഅ്ല(റ)യോട് വരാൻ സൂചന നൽകി. ഉടൻ യഅ്ല(റ) നബി(സ)യുടെ അടുത്തെത്തി തന്റെ തല കാട്ടി. നബി(സ)യുടെ മുഖം ചുവന്നു തുടുത്തിരിക്കുന്നു. അൽപ സമയം കൂർക്കം വലിക്കുന്നതുപോലെ ഒരു ശബ്ദമുണ്ടായി. ആ അവസ്ഥ വിട്ടു മാറി. ഉടനെ നബി(സ) ചോദിച്ചു: "ഉംറയെക്കുറിച്ച് ചോദിച്ച ആളെവിടെ." അദ്ദേഹത്തെ അവർ അവിടെ എത്തിച്ചു. നബി(സ) പറഞ്ഞു: "ശരീരത്തിലെ സുഗന്ധം മൂന്ന് തവണ കഴുകുക. ജുബ്ബ അഴിക്കുക. ഹജ്ജിൽ ചെയ്യുന്ന പോലെ ഉംറയിലും ചെയ്യുക." (ബു,മു)', 'صَفْوَانَ بْنِ يَعْلَى بْنِ أُمَيَّةَ', 'സ്വഫ്വാനുബ്നു യഅ്ലബ്നു ഉമയ്യ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 79, 80, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا أُنْزِلَ عَلَيْهِ الْوَحْيُ نَكَسَ رَأْسَهُ وَنَكَسَ أَصْحَابُهُ رُءُوسَهُمْ، فَلَمَّا أُتْلِيَ عَنْهُ رَفَعَ رَأْسَهُ. (م)', 'ഉബാദതുബ്നുസ്സ്വാമിത്(റ): നബി(സ)ക്ക് വഹ്യ് അവതരിക്കുമ്പോൾ അവിടുന്ന് തല കുനിക്കും. അനുചരന്മാരും തല കുനിക്കും. അവതരിച്ചു കഴിഞ്ഞാൽ തല ഉയർത്തും. (മു)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നുസ്സ്വാമിത്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 80, 80, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
